        def strip_quotes(path):
            # Remove ONLY a single " from start/end if present
            if path.startswith('"') and path.endswith('"'):
                return path[1:-1]
            elif path.startswith('"'):
                return path[1:]
            elif path.endswith('"'):
                return path[:-1]
            else:
                return path

